/* 繁轉簡詞組優先修正表 */
var T2S_PHRASES = [
  ['記憶體','内存'],['記憶卡','记忆卡'],['資訊','信息'],['螢幕','屏幕'],
  ['預設','默认'],['選單','菜单'],['檔案','文件'],['品質','质量'],
  ['網路','网络'],['滑鼠','鼠标'],['計時器','计时器'],['點擊','点击'],
  ['關閉','关闭'],['開啟','开启'],['開關','开关'],['檯燈','台灯'],
  ['櫃檯','柜台'],['檯面','台面'],['手術檯','手术台'],['借書台','借书台'],
  ['發霉','发霉'],['發黴','发霉'],['菸蒂','烟蒂'],['抽菸','抽烟'],
  ['腳踏車','自行车'],['手電筒','手电筒'],['保溫杯','保温杯'],['原子筆','圆珠笔'],
  ['身份證','身份证'],['複印件','复印件'],['錄音機','录音机'],['留聲機','留声机']
];

function toSimplified(str){
  if(!str || typeof str !== 'string') return str;
  var s = str;
  for(var i=0;i<T2S_PHRASES.length;i++){
    var p = T2S_PHRASES[i];
    if(s.indexOf(p[0]) !== -1) s = s.split(p[0]).join(p[1]);
  }
  var out = '';
  for(var j=0;j<s.length;j++){
    var ch = s[j];
    out += T2S_CHAR[ch] || ch;
  }
  return out;
}

