function ownedArcana(){ return lsJSON(LS_ARCANA, []); }
function activeArcanaId(){ return lsGet(LS_ARC_CUR) || ''; }
function arcanaById(id){
  for(var i=0;i<ARCANA_CARDS.length;i++) if(ARCANA_CARDS[i].id === id) return ARCANA_CARDS[i];
  return null;
}
function drawRandomArcana(){
  var pick = ARCANA_CARDS[Math.floor(Math.random() * ARCANA_CARDS.length)];
  var owned = ownedArcana();
  if(owned.indexOf(pick.id) === -1){
    owned.push(pick.id);
    lsSet(LS_ARCANA, JSON.stringify(owned));
  }
  lsSet(LS_ARC_CUR, pick.id);
  if(owned.length >= 1 && typeof unlockAchievement === 'function') unlockAchievement('v53_arcana_first');
  if(owned.length >= ARCANA_CARDS.length && typeof unlockAchievement === 'function') unlockAchievement('v53_arcana_all');
  if(window.V5Audio && typeof V5Audio.sfx === 'function') V5Audio.sfx('sigilEquip');
  if(typeof showToast === 'function') showToast('占卜命牌 · ' + pick.num + ' ' + pick.name);
  return pick;
}

